-- Этап B, пачка 1/7 — сводка отзывов (обработанная аналитика на основе веб-поиска
-- по агрегаторам: otzovik.com, vuzopedia.ru, tabiturient.ru, ucheba.ru, tutortop.ru,
-- Яндекс.Карты и др.). Заполняю feedback_summary_student — большинство найденных
-- отзывов написаны студентами/абитуриентами; feedback_summary_parent/teacher/
-- career_counselor/alumnus оставляю пустыми, т.к. по ним отдельного массива
-- отзывов не нашёл (не выдумываю).

update public.institutions set
  feedback_summary_student = 'Отзывы студентов в основном положительные: отмечают атмосферу строгости и профессионализма, сильный преподавательский состав, сохранение традиций русской балетной школы. Но встречаются и жёсткие оценки: высокая конкуренция, отсутствие дружеской атмосферы, риск отчисления. Поступать стоит, только трезво оценив здоровье, характер и готовность к нагрузке.',
  feedback_positive_highlights = '{"профессионализм преподавателей","сохранение традиций классического балета","высокий уровень подготовки"}',
  feedback_negative_highlights = '{"жёсткая конкуренция между студентами","риск отчисления и сложность возврата в обычную школу","эмоционально тяжёлая атмосфера"}',
  feedback_based_on_count = 6, feedback_generated_at = now(), updated_at = now()
where name = 'Академия Русского балета имени А.Я. Вагановой' and city = 'Санкт-Петербург';

update public.institutions set
  feedback_summary_student = 'Судя по агрегированной статистике отзывов (43 отзыва: 88% положительных), студенты в целом довольны: качественная материально-техническая база, сильные преподаватели, развитая студенческая жизнь и спорт. Регулярно отмечается, что учиться сложно — спрашивают строго — но при должном старании обучение того стоит.',
  feedback_positive_highlights = '{"качественная материально-техническая база","сильный преподавательский состав","развитая студенческая жизнь и спорт"}',
  feedback_negative_highlights = '{"высокая сложность обучения","строгий спрос на экзаменах"}',
  feedback_based_on_count = 43, feedback_generated_at = now(), updated_at = now()
where name = 'Балтийский государственный технический университет ВОЕНМЕХ им. Д.Ф. Устинова' and city = 'Санкт-Петербург';

update public.institutions set
  feedback_summary_student = 'Отзывы неоднородны. Сильные стороны: качественные корпуса и общежития, серьёзная лабораторная база, хорошие связи с местами практики (особенно для инженерных/нефтегазовых специальностей), сильный преподавательский состав. Заметная критика — слабая связь студентов с руководством вуза («их не ставят ни во что»), негибкая система экзаменов без пересдач, жёсткие требования (обязательная форма, посещаемость).',
  feedback_positive_highlights = '{"современные корпуса и общежития","сильная лабораторная база","хорошие связи с работодателями отрасли"}',
  feedback_negative_highlights = '{"слабая обратная связь с администрацией","жёсткие формальные требования","экзамены без права пересдачи"}',
  feedback_based_on_count = 10, feedback_generated_at = now(), updated_at = now()
where name = 'Санкт-Петербургский горный университет императрицы Екатерины II' and city = 'Санкт-Петербург';

update public.institutions set
  feedback_summary_student = 'Отзывы противоречивые. Плюсы: международные партнёрства, практика в отелях, обмен с зарубежными вузами. Минусы — значительные: жалобы на недостаточную квалификацию части преподавателей, нерелевантные предметы в программе, плохую организацию расписания сессий, отдельные упоминания поборов.',
  feedback_positive_highlights = '{"международные стажировки и партнёрства","практика в реальных отелях"}',
  feedback_negative_highlights = '{"квалификация части преподавателей вызывает вопросы","плохая организация расписания","жалобы на поборы"}',
  feedback_based_on_count = 11, feedback_generated_at = now(), updated_at = now()
where name = 'Балтийская академия туризма и предпринимательства' and city = 'Санкт-Петербург';

update public.institutions set
  feedback_summary_student = 'Небольшой частный вуз с неоднозначными отзывами. Плюсы: доступный порог поступления, человеческое отношение преподавателей и руководства, лояльные требования. Минусы: скромные условия (несколько кабинетов, состояние помещений оставляет желать лучшего), встречаются намёки на непрозрачный подбор части преподавателей.',
  feedback_positive_highlights = '{"доступность поступления","человеческое отношение преподавателей"}',
  feedback_negative_highlights = '{"скромная материальная база и состояние помещений","непрозрачность части кадровых решений"}',
  feedback_based_on_count = 5, feedback_generated_at = now(), updated_at = now()
where name = 'Балтийский гуманитарный институт' and city = 'Санкт-Петербург';

update public.institutions set
  feedback_summary_student = 'Воспринимается как одна из немногих серьёзных частных альтернатив государственным вузам города. Отзывы подчёркивают домашнюю атмосферу, сильных преподавателей-исследователей, содержательное общение со студентами. Из минусов — теснота помещений, не соответствующая статусу вуза, и высокий порог сложности обучения (подходит не всем).',
  feedback_positive_highlights = '{"сильные преподаватели-исследователи","камерная, "домашняя" атмосфера","высокий академический уровень"}',
  feedback_negative_highlights = '{"тесные помещения","высокий порог требований к студентам"}',
  feedback_based_on_count = 6, feedback_generated_at = now(), updated_at = now()
where name = 'Европейский университет в Санкт-Петербурге' and city = 'Санкт-Петербург';

update public.institutions set
  feedback_summary_student = 'Входит в топ-100 вузов по версии Forbes. Отзывы хвалят насыщенную студенческую жизнь (конференции, кружки, WorldSkills) и увлечённых преподавателей технических дисциплин. Критика — расхождение заявленной и реальной программы обучения, повторение материала между курсами, нехватка профильных дисциплин на некоторых направлениях.',
  feedback_positive_highlights = '{"насыщенная студенческая жизнь и конкурсы","увлечённые преподаватели технических дисциплин","высокая трудоустраиваемость выпускников"}',
  feedback_negative_highlights = '{"расхождение заявленной и фактической программы","повторение материала между курсами"}',
  feedback_based_on_count = 8, feedback_generated_at = now(), updated_at = now()
where name = 'Санкт-Петербургский государственный университет аэрокосмического приборостроения' and city = 'Санкт-Петербург';

update public.institutions set
  feedback_summary_student = 'Отзывы неоднородны. Плюсы: серьёзная морская практика, реальные кейсы, преподаватели с практическим опытом, воспитание в традициях флота. Минусы — заметные: жалобы на организацию заочного отделения, несовпадение заявленных сроков обучения с реальными, состояние отдельных корпусов.',
  feedback_positive_highlights = '{"сильная практическая/морская подготовка","преподаватели с реальным опытом работы во флоте"}',
  feedback_negative_highlights = '{"плохая организация заочного отделения","несовпадение заявленных и реальных сроков обучения","состояние отдельных корпусов"}',
  feedback_based_on_count = 30, feedback_generated_at = now(), updated_at = now()
where name = 'Государственный университет морского и речного флота имени адмирала С.О. Макарова' and city = 'Санкт-Петербург';

update public.institutions set
  feedback_summary_student = 'Отзывов немного, но преимущественно положительные: студенты хвалят индивидуальный подход к каждому, погружение в традицию русской академической живописи, мастер-классы от практикующих художников. Явных негативных паттернов в найденных источниках не обнаружено — возможно, из-за небольшого числа опубликованных отзывов.',
  feedback_positive_highlights = '{"индивидуальный подход к каждому студенту","погружение в традицию академической живописи","мастер-классы практикующих художников"}',
  feedback_negative_highlights = '{}',
  feedback_based_on_count = 2, feedback_generated_at = now(), updated_at = now()
where name = 'Санкт-Петербургская академия художеств имени Ильи Репина' and city = 'Санкт-Петербург';
